#!/bin/bash
# SOURCE 3 -- the machine search, then 50 null runs at the same budget, then
# the gates and the write-up. ONE armed stage, no manual step between parts.
#
# DO NOT EDIT THIS FILE WHILE IT IS RUNNING. Bash reads a script incrementally
# as it executes; editing exit6.sh mid-run on 25 Nov is why that rule is
# written down in three places now.
cd /Users/jackcuster/fx-data
export FX_COST_TABLE=results/cost_table_h22.csv
LOG=results/chainlogs/src3.log
ts(){ date "+[%H:%M:%S]"; }

echo "$(ts) START src3" >> $LOG

echo "$(ts) START src3 real search (200,000 random + 200,000 local + 200,000 replication)" >> $LOG
python3 code/nnfxsrc3.py --real >> $LOG 2>&1 \
  && echo "$(ts) OK src3 real" >> $LOG || { echo "$(ts) FAIL src3 real" >> $LOG; exit 1; }

# 50 independent null runs, 8 at a time. Resumable: a run whose csv is already
# on disk is skipped, so a killed batch costs the runs in flight and no more.
echo "$(ts) START src3 search null, 50 runs, 8 workers" >> $LOG
seq 0 49 | xargs -P 8 -I{} sh -c \
  'FX_COST_TABLE=results/cost_table_h22.csv python3 code/nnfxsrc3.py --null-run {} >> results/chainlogs/src3_null_{}.log 2>&1'
NDONE=$(ls results/nnfx/src3_null/null_*.csv 2>/dev/null | wc -l | tr -d ' ')
echo "$(ts) OK src3 null -- $NDONE of 50 runs on disk" >> $LOG

echo "$(ts) START src3 finish (floor, gates on survivors, SOURCE3.md)" >> $LOG
python3 code/nnfxsrc3.py --finish >> $LOG 2>&1 \
  && echo "$(ts) OK src3 finish" >> $LOG || echo "$(ts) FAIL src3 finish" >> $LOG

echo "$(ts) START preflight" >> $LOG
python3 code/preflight.py >> $LOG 2>&1 && echo "$(ts) OK preflight" >> $LOG \
  || echo "$(ts) FAIL preflight" >> $LOG
echo "$(ts) DONE src3" >> $LOG
